pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1234);
        address caddress = address(0x5678);
        address[] memory emptyTos = new address[](0);
        uint v = 100;

        // The reference requires _tos.length > 0, so with empty array it should revert.
        // The buggy mutant removes that require, so it returns true.
        bool ok;
        try c.transfer(from, caddress, emptyTos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference satisfies: ok == false (revert). The buggy does: ok == true (no revert).
        assertTrue(!ok, "transfer with empty _tos should revert (reference behavior)");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a simple ERC20-like token to track transferFrom calls
        // We'll deploy a mock token that counts calls
        TokenMock token = new TokenMock();
        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);
        vm.prank(address(0xdead));
        c.transfer(address(this), address(token), tos, 100);
        // Reference: both transfers happened => count = 2
        // Bug: last tos[1] skipped => count = 1
        assertTrue(token.transferCount() == 2);
    }
}

contract TokenMock {
    uint256 public transferCount;
    function transferFrom(address, address, uint256) external returns (bool) {
        transferCount++;
        return true;
    }
}

